import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import type {ReactNode} from 'react';
import {Text,View,type ViewProps} from 'react-native';
import {Button} from '@/components/nyc-tron/ui/components/Button';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {controlIdentity,useScopedControl,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {assertFrameRate,type FrameRate} from '@/components/nyc-tron/ui/components/forge/timebase';
import {TransportControls} from '@/components/nyc-tron/ui/components/forge/timeline/TransportControls';
import {TimecodeDisplay} from '@/components/nyc-tron/ui/components/forge/timeline/TimecodeDisplay';
import {SeekBar} from '@/components/nyc-tron/ui/components/forge/timeline/SeekBar';
import {SafeAreaOverlay,type SafeAreaOverlayProps} from '@/components/nyc-tron/ui/components/forge/timeline/SafeAreaOverlay';
import {setMark,type InOutRange} from '@/components/nyc-tron/ui/components/forge/timeline/edits';
import {space} from '@/components/nyc-tron/ui/tokens';
export interface MediaMonitorProps extends Omit<ViewProps,'children'>,ScopedControlProps {
 kind:'source'|'program';sourceId:string|null;label:string;frame:number;durationFrames:number;rate:FrameRate;playing:boolean;
 /** Last decoded frame actually presented, separate from the requested/clock frame. */
 presentedFrame?:number;status:'empty'|'loading'|'ready'|'error';error?:string;
 /** Actual native video/compositor surface owned by the consuming host. */
 surface:ReactNode;aspectRatio:number;overlays?:ReactNode;
 onPlayPause:(signal?:AbortSignal)=>void|Promise<unknown>;onStop:(signal?:AbortSignal)=>void|Promise<unknown>;
 onSeek:(frame:number,signal?:AbortSignal)=>void|Promise<unknown>;onScrub?:(frame:number)=>void;
 onOpenSource?:(signal?:AbortSignal)=>void|Promise<unknown>;
 range?:InOutRange;onRangeChange?:(range:InOutRange,signal?:AbortSignal)=>void|Promise<unknown>;
 safeArea?:Omit<SafeAreaOverlayProps,'aspect'>;unstyled?:boolean;
}
/** Shared monitor chrome. Surface/decoder lifetimes stay above source/program layouts. */
export function MediaMonitor({scope='media-monitor',revision=0,...props}:MediaMonitorProps){
 const {kind,sourceId,label,frame,durationFrames,rate,playing,presentedFrame,status,error,surface,aspectRatio,overlays,onPlayPause:_play,onStop:_stop,onSeek:_seek,onScrub,onOpenSource,range,onRangeChange,safeArea,unstyled=false,disabledReason,style,...rest}=props;
 assertFrameRate(rate);
 if(!label.trim()||label.length>1024||sourceId!==null&&(!sourceId.trim()||sourceId.length>512)||!Number.isSafeInteger(frame)||frame<0||!Number.isSafeInteger(durationFrames)||durationFrames<0||presentedFrame!==undefined&&(!Number.isSafeInteger(presentedFrame)||presentedFrame<0)||!Number.isFinite(aspectRatio)||aspectRatio<=0||aspectRatio>10||!['empty','loading','ready','error'].includes(status))throw new RangeError('Invalid monitor state');
 const identity=JSON.stringify([...controlIdentity(scope,revision),sourceId,durationFrames,rate,disabledReason]);
 const owner=JSON.stringify([identity,status]);
 const openGuard=useScopedControl(identity,props,disabledReason!==undefined);
 const guard=useScopedControl(owner,props,disabledReason!==undefined||status!=='ready'||openGuard.pending),off=guard.pending||openGuard.pending||disabledReason!==undefined||status!=='ready';
 const seek=(value:number)=>guard.run('seek',(host,signal)=>host.onSeek(value,signal));
 const reason=disabledReason??(openGuard.pending?'Opening source media':guard.pending?'Player operation in progress':status==='loading'?'Loading media':status==='error'?(error??'Media could not be loaded'):status==='empty'?'Open media to begin':undefined);
 return <View {...rest} style={[{gap:space[2],minWidth:0},style]} accessibilityLabel={label}>
  <View style={{aspectRatio,position:'relative',overflow:'hidden',minHeight:120}}>
   {surface}{kind==='program'&&safeArea?<SafeAreaOverlay {...safeArea} aspect={aspectRatio} unstyled={unstyled}/>:null}{overlays}
  </View>
  <Text {...{className:unstyled?undefined:'text-text'}}>Presented frame: {presentedFrame===undefined?'Not reported':presentedFrame}</Text>
  <TimecodeDisplay key={owner} scope={scope} revision={revision} frame={frame} rate={rate} format="timecode" durationFrames={durationFrames} label={kind==='source'?'Source time':'Program time'} unstyled={unstyled} {...(off?{disabledReason:reason??'Player unavailable'}:{})} onCommit={seek}/>
  <SeekBar key={owner} scope={scope} revision={revision} frame={frame} rate={rate} durationFrames={durationFrames} disabled={off} unstyled={unstyled} onSeek={seek} {...(onScrub?{onScrub:(value:number)=>guard.current()?.onScrub?.(value)}:{})}/>
  <TransportControls key={owner} scope={scope} revision={revision} frame={frame} durationFrames={durationFrames} playing={playing} unstyled={unstyled} {...(reason?{disabledReason:reason}:{})}
   onSeek={seek} onPlayPause={()=>guard.run('play',(host,signal)=>host.onPlayPause(signal))} onStop={()=>guard.run('stop',(host,signal)=>host.onStop(signal))}/>
  {kind==='source'&&range&&onRangeChange?<View style={{flexDirection:'row',flexWrap:'wrap',gap:space[2]}}>
   <Button title="Mark source in" disabled={off} unstyled={unstyled} onPress={()=>guard.run('in',(host,signal)=>host.onRangeChange?.(setMark(host.range!,'in',host.frame,host.durationFrames),signal))}/>
   <Button title="Mark source out" disabled={off} unstyled={unstyled} onPress={()=>guard.run('out',(host,signal)=>host.onRangeChange?.(setMark(host.range!,'out',host.frame,host.durationFrames),signal))}/>
   <Button title="Clear source marks" disabled={off} variant="secondary" unstyled={unstyled} onPress={()=>guard.run('clear',(host,signal)=>host.onRangeChange?.({},signal))}/>
   <Text {...{className:unstyled?undefined:'text-text'}}>In: {range.inFrame??'Not set'}; out: {range.outFrame??'Not set'}</Text>
  </View>:null}
  {onOpenSource?<Button title="Open source media" disabled={guard.pending||openGuard.pending||disabledReason!==undefined} unstyled={unstyled} onPress={()=>openGuard.run('open',(host,signal)=>host.onOpenSource?.(signal))}/>:null}
  <ErrorMessage message={guard.error??openGuard.error??(status==='error'?error:undefined)??undefined} unstyled={unstyled}/>
 </View>;
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

